async (page) => {
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  const base = 'http://127.0.0.1:8769/prototype-decisions.html';
  const out = 'docs/design-review/';
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.goto(base + '?variant=A');
  await page.screenshot({ path: out + 'decisions-layout-a.png' });
  await page.getByRole('button', { name: 'Histórico', exact: false }).click();
  await page.getByRole('button', { name: 'v2', exact: true }).click();
  await page.getByText('Versão anterior · somente leitura.', { exact: false }).waitFor();
  await page.screenshot({ path: out + 'decisions-history.png' });
  await page.getByRole('button', { name: 'Exportar…', exact: true }).click();
  await page.getByRole('dialog').waitFor();
  await page.locator('#format').selectOption('JSON');
  const jsonPreview = await page.locator('#exportPreview').textContent();
  if (JSON.parse(jsonPreview).version !== 3) throw new Error('A exportação precisa indicar a versão atual');
  await page.screenshot({ path: out + 'decisions-export.png' });
  await page.getByRole('button', { name: 'Cancelar', exact: true }).click();
  await page.getByRole('textbox', { name: 'Buscar decisões do projeto', exact: true }).fill('zzzznenhuma');
  await page.getByText('Nenhuma decisão encontrada', { exact: true }).waitFor();
  await page.screenshot({ path: out + 'decisions-empty-search.png' });
  await page.getByRole('textbox', { name: 'Buscar decisões do projeto', exact: true }).fill('cofre');
  await page.getByRole('heading', { name: 'Onde armazenar credenciais do provedor?', exact: true }).waitFor();
  await page.goto(base + '?variant=B');
  await page.screenshot({ path: out + 'decisions-layout-b.png' });
  await page.getByRole('cell', { name: 'Como garantir uma única decisão por captura?', exact: true }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'Histórico', exact: false }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'v1', exact: true }).click();
  await page.getByRole('dialog').getByText('Versão anterior · somente leitura.', { exact: false }).waitFor();
  await page.goto(base + '?variant=C');
  await page.screenshot({ path: out + 'decisions-layout-c.png' });
  await page.getByRole('button', { name: 'Próximo estudo', exact: true }).click();
  if (!page.url().endsWith('variant=A')) throw new Error('O seletor precisa atualizar a variante na URL');
  await page.setViewportSize({ width: 1180, height: 760 });
  await page.screenshot({ path: out + 'decisions-compact.png' });
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
  if (overflow) throw new Error('Overflow horizontal da janela compacta');
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.goto(base + '?variant=A');
  if (errors.length) throw new Error(errors.join('\n'));
  return { variants: ['A', 'B', 'C'], checks: ['histórico somente leitura', 'exportação da versão atual', 'busca sem resultados', 'busca no motivo', 'histórico no catálogo', 'seletor com URL', 'janela compacta sem overflow'], errors };
}
